    <script id="MathJax-script" async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"></script>
    <style>
        body {
            font-family: "Microsoft YaHei", "SimHei", sans-serif;
            background-color: #fff;
            color: #333;
            line-height: 1.5;
            margin: 0;
            padding: 20px;
        }
        .page-container {
            max-width: 850px;
            margin: 0 auto;
            position: relative;
            padding-bottom: 60px;
        }
        .placeholder {
            background-color: #f5f5f5;
            border: 2px dashed #bbb;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #666;
            font-style: italic;
            text-align: center;
            padding: 10px;
            box-sizing: border-box;
        }
        .red-text { color: #d32f2f; }
        .brown-text { color: #8d6e63; }

        /* Header styles */
        .header-wrapper {
            display: flex;
            justify-content: center;
            align-items: center;
            margin-bottom: 40px;
        }
        .header-deco-1 { width: 18px; height: 18px; background-color: #B39DDB; transform: rotate(45deg); margin-right: -8px; z-index: 1; }
        .header-deco-2 { width: 28px; height: 28px; background-color: #7E57C2; transform: rotate(45deg); margin-right: -12px; z-index: 2; }
        .header-deco-3 { width: 18px; height: 18px; background-color: #B39DDB; transform: rotate(45deg); margin-right: 15px; z-index: 1; }
        .header-title {
            background: linear-gradient(to bottom, #9B70C4, #7E57C2);
            color: white;
            padding: 8px 30px;
            font-size: 24px;
            font-weight: bold;
            border-radius: 0 15px 15px 0;
            border-bottom: 3px solid #5E35B1;
            letter-spacing: 5px;
        }

        /* Section layout */
        .q-header {
            display: flex;
            align-items: flex-start;
            margin-bottom: 15px;
        }
        .q-icon {
            background-color: #e57373;
            color: white;
            width: 30px;
            height: 30px;
            border-radius: 50% 50% 50% 0;
            display: flex;
            justify-content: center;
            align-items: center;
            font-weight: bold;
            font-size: 18px;
            margin-right: 10px;
            transform: rotate(-45deg);
            flex-shrink: 0;
        }
        .q-icon span { transform: rotate(45deg); }
        .q-text {
            font-size: 17px;
            flex: 1;
        }

        /* Arrows */
        .arrow-right {
            display: inline-block;
            width: 40px;
            height: 2px;
            background: #d32f2f;
            position: relative;
            margin: 0 10px;
            vertical-align: middle;
        }
        .arrow-right::after {
            content: ''; position: absolute; right: 0; top: -4px;
            border-top: 5px solid transparent; border-bottom: 5px solid transparent; border-left: 10px solid #d32f2f;
        }
        .arrow-down {
            display: block;
            width: 2px;
            height: 25px;
            background: #d32f2f;
            position: relative;
            margin: 5px auto;
        }
        .arrow-down::after {
            content: ''; position: absolute; bottom: -5px; left: -4px;
            border-left: 5px solid transparent; border-right: 5px solid transparent; border-top: 10px solid #d32f2f;
        }

        /* Bubbles */
        .bubble {
            border: 1px solid #80DEEA;
            border-radius: 20px;
            padding: 8px 15px;
            background: #E0F7FA;
            font-size: 14px;
            color: #00838F;
            position: relative;
            display: inline-block;
            box-shadow: 1px 1px 3px rgba(0,0,0,0.05);
            text-align: center;
        }
        .bubble-left::after {
            content: ''; position: absolute; bottom: -12px; right: 30%;
            border-width: 12px 10px 0 0; border-style: solid; border-color: #80DEEA transparent transparent transparent;
        }
        .bubble-left::before {
            content: ''; position: absolute; bottom: -10px; right: 31%;
            border-width: 11px 9px 0 0; border-style: solid; border-color: #E0F7FA transparent transparent transparent;
            z-index: 1;
        }
        .bubble-right::after {
            content: ''; position: absolute; bottom: -12px; left: 30%;
            border-width: 12px 0 0 10px; border-style: solid; border-color: #80DEEA transparent transparent transparent;
        }
        .bubble-right::before {
            content: ''; position: absolute; bottom: -10px; left: 31%;
            border-width: 11px 0 0 9px; border-style: solid; border-color: #E0F7FA transparent transparent transparent;
            z-index: 1;
        }

        /* Section 1 */
        .s1-bus-img { width: 100%; height: 180px; margin-bottom: 10px; border-radius: 5px; }
        .s1-middle-row { display: flex; justify-content: space-between; align-items: flex-start; margin-top: 20px; }
        .s1-line-diag { width: 320px; height: 100px; margin: 0 auto 15px; }

        /* Section 2 */
        .s2-row { display: flex; justify-content: space-between; margin-top: 20px; }
        .s2-col-left { width: 28%; display: flex; flex-direction: column; align-items: center; }
        .s2-col-center { width: 50%; display: flex; flex-direction: column; align-items: center; }
        .s2-col-right { width: 18%; display: flex; flex-direction: column; align-items: center; padding-top: 100px; }
        .s2-grid { width: 250px; height: 150px; }

        /* Footer */
        .footer-note {
            color: #8d6e63;
            font-size: 13px;
            margin-top: 40px;
            border-top: 1px solid #f0f0f0;
            padding-top: 15px;
            line-height: 1.6;
        }
        .page-num-container {
            position: absolute;
            bottom: 0;
            right: 0;
            display: flex;
            align-items: center;
            font-size: 20px;
            font-weight: bold;
        }
    </style>
